use super::*;

/// The `list` view: memories newest-first, narrowed by [`Filter`]. Pure over a slice so the ordering
/// and filtering are tested without a store.
pub fn filter_and_order<'a>(items: &'a [Memory], f: &Filter) -> Vec<&'a Memory> {
    let mut v: Vec<&Memory> = items
        .iter()
        .filter(|i| f.tag.is_none_or(|t| i.has_tag(t)))
        .filter(|i| f.status.is_none_or(|s| i.status.eq_ignore_ascii_case(s)))
        .filter(|i| f.link.is_none_or(|r| i.links_to(r)))
        .filter(|i| f.rel.is_none_or(|r| i.has_rel(r)))
        .filter(|i| f.horizon.is_none_or(|h| i.horizon.eq_ignore_ascii_case(h)))
        .filter(|i| f.kind.is_none_or(|k| i.is_kind(k)))
        .collect();
    // Newest first — the last thought is usually the one you are looking for.
    v.sort_by(|a, b| b.created_at_ms.cmp(&a.created_at_ms).then(b.id.cmp(&a.id)));
    v
}
